import { supabase } from '@/lib/supabase'
import { notFound } from 'next/navigation'

export const dynamic = 'force-dynamic'
import { Suspense } from 'react'
import TopNav from '@/components/farmer/TopNav'
import FarmCover from '@/components/farmer/FarmCover'
import TrustStrip from '@/components/farmer/TrustStrip'
import TabSection from '@/components/farmer/TabSection'
import { CartFab } from '@/components/consumer/Cart'

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, name, village, district, story_quote')
    .eq('slug', slug)
    .single()

  if (!farmer) return { title: 'Farmer not found' }

  const { data: firstPhoto } = await supabase
    .from('media')
    .select('url')
    .eq('farmer_id', farmer.id)
    .eq('type', 'photo')
    .order('sort_order', { ascending: true })
    .limit(1)
    .single()

  const title = `${farmer.name} — Natural farmer in ${farmer.village}`
  const description =
    farmer.story_quote ??
    `Buy natural produce directly from ${farmer.name}, ${farmer.village}, ${farmer.district}. No middlemen. No chemicals.`

  return {
    title: `${farmer.name}'s Farm — YourFamilyFarmer`,
    description,
    openGraph: {
      title,
      description,
      siteName: 'YourFamilyFarmer',
      ...(firstPhoto?.url ? { images: [{ url: firstPhoto.url, width: 1200, height: 630, alt: `${farmer.name}'s farm` }] } : {}),
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      ...(firstPhoto?.url ? { images: [firstPhoto.url] } : {}),
    },
  }
}

export default async function FarmerPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('*')
    .eq('slug', slug)
    .eq('active', true)
    .single()

  if (!farmer) notFound()

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('created_at', { ascending: false })

  const { data: reviews } = await supabase
    .from('reviews')
    .select('*')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  // Verified per-order buyer feedback (the ⭐ button consumers tap on their
  // orders) lives in produce_reviews, tied to a listing. Only feedback on a
  // completed order is approved/public. Surface it on the farmer's profile too —
  // tagged with the produce it was about — so consumer feedback isn't invisible
  // here, and fold it into the same Reviews tab + star average as written reviews.
  const { data: produceReviews } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at, produce_listing_id')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  // Resolve the produce names with a separate query rather than a PostgREST
  // embedded join (produce_reviews → produce_listings). That relationship isn't
  // in the schema cache, so embedding it made the whole produce_reviews query
  // error out and return null — which silently hid ALL verified buyer feedback
  // from the profile (showing "No reviews yet" and a 0 rating even when approved
  // reviews existed).
  const listingIds = [
    ...new Set((produceReviews ?? []).map((r) => r.produce_listing_id).filter(Boolean) as string[]),
  ]
  const { data: listingNames } = listingIds.length
    ? await supabase.from('produce_listings').select('id, name').in('id', listingIds)
    : { data: [] as { id: string; name: string }[] }
  const nameById = new Map((listingNames ?? []).map((l) => [l.id, l.name]))

  const mappedProduceReviews = (produceReviews ?? []).map((r) => ({
    id: r.id,
    reviewer_name: r.reviewer_name,
    star_rating: r.star_rating,
    review_text: r.review_text,
    produce_ordered: r.produce_listing_id ? nameById.get(r.produce_listing_id) ?? null : null,
    created_at: r.created_at,
  }))

  // Both sources, newest first — one combined list for the Reviews tab.
  const allReviews = [...(reviews ?? []), ...mappedProduceReviews].sort(
    (a, b) => new Date(b.created_at as string).getTime() - new Date(a.created_at as string).getTime(),
  )

  // Star rating shown in the trust strip reflects all real feedback (written
  // reviews + verified order feedback). Falls back to the stored value if there
  // are no reviews yet.
  const ratingAvg =
    allReviews.length > 0
      ? Math.round(
          (allReviews.reduce((sum, r) => sum + ((r.star_rating as number) ?? 0), 0) / allReviews.length) * 10,
        ) / 10
      : (farmer.rating_avg ?? 0)

  const { data: media } = await supabase
    .from('media')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('sort_order', { ascending: true })

  return (
    <main className="min-h-screen bg-gray-50 pb-24">
      <TopNav regionSlug={farmer.region_slug} />
      <FarmCover farmer={farmer} />
      {/* Count only live listings — a produce the farmer has suspended (or that
          is still "coming soon") must not inflate the public "Produce now" stat. */}
      <TrustStrip
        farmer={{ ...farmer, rating_avg: ratingAvg }}
        produceCount={(produce ?? []).filter((p) => (p as { status?: string }).status === 'available').length}
      />
      <Suspense fallback={null}>
        <TabSection
          farmer={farmer}
          produce={produce ?? []}
          reviews={allReviews}
          media={media ?? []}
        />
      </Suspense>
      <CartFab />
    </main>
  )
}

const statusBadge = (s: Order['status']) =>
  s === 'approved' ? 'bg-green-100 text-green-800'
    : s === 'declined' ? 'bg-red-100 text-red-700'
    : s === 'cancelled' ? 'bg-gray-200 text-gray-700'
    : 'bg-amber-100 text-amber-800'

const statusText = (s: Order['status']) =>
  s === 'approved' ? tx.statusApproved
    : s === 'declined' ? tx.statusDeclined
    : s === 'cancelled' ? L('Cancelled by buyer', 'కొనుగోలుదారు రద్దు చేశారు')
    : L('Pending', 'పెండింగ్')

const paymentText = (o: Order) => {
  if (!o.payment_method || o.payment_method === 'cod')
    return isPaid ? L('Cash — Received', 'నగదు — అందింది') : 'Payment Pending (COD)'
  // Online payments come through the Razorpay gateway (stored as 'razorpay';
  // some legacy orders use 'upi'). Never surface the gateway name "razorpay"
  // to the farmer — show "UPI".
  if (o.payment_method === 'upi' || o.payment_method === 'razorpay')
    return isPaid ? L('UPI — Paid', 'UPI — చెల్లించారు')
      : (o.payment_status === 'payment_claimed' || o.payment_status === 'pending_confirmation')
        ? L('UPI — Buyer paid, verify', 'UPI — ధృవీకరించండి')
        : L('Payment Pending', 'చెల్లింపు పెండింగ్')
  return o.payment_method
}

// Fulfilment milestones (created → confirmed → shipped/ready → received/picked).
const milestones: { label: string; at: string | null; done: boolean }[] = order
  ? (() => {
      const approved = order.status === 'approved'
      const base = [
        { label: L('Order placed', 'ఆర్డర్ వచ్చింది'), at: order.created_at, done: true },
        { label: L('Approved by you', 'మీరు ఆమోదించారు'), at: order.confirmed_at, done: approved || !!order.collected_at || !!order.received_at },
      ]
      if (isDelivery && (order.assigned_at || order.delivery_status)) {
        return [
          ...base,
          { label: L('Rider assigned', 'రైడర్ కేటాయించారు'), at: order.assigned_at, done: !!order.assigned_at },
          { label: L('Picked up by rider', 'రైడర్ తీసుకున్నారు'), at: order.picked_up_at, done: !!order.picked_up_at },
          { label: L('Out for delivery', 'డెలివరీకి బయలుదేరారు'), at: order.out_for_delivery_at, done: !!order.out_for_delivery_at },
          { label: L('Delivered', 'డెలివరీ అయింది'), at: order.delivered_at, done: order.delivery_status === 'delivered' },
        ]
      }
      if (isDelivery || isCourier) {
        return [
          ...base,
          { label: L('Shipped', 'షిప్ చేశారు'), at: order.shipped_at, done: !!order.shipped_at },
          { label: L('Received by buyer', 'కొనుగోలుదారు అందుకున్నారు'), at: order.received_at, done: !!order.received_at },
        ]
      }
      return [
        ...base,
        { label: L('Shipped', 'షిప్ చేశారు'), at: order.shipped_at, done: !!order.shipped_at },
        { label: L('Picked up by buyer', 'కొనుగోలుదారు తీసుకున్నారు'), at: order.collected_at, done: !!order.collected_at },
      ]
    })()
  : []

return (
  <main className="min-h-screen bg-gray-50 pb-16">
    <div className="bg-green-900 px-4 pt-6 pb-10">
      <Link href="/farmer/dashboard/orders" className="text-green-300 text-sm flex items-center gap-1 mb-4">
        ← {tx.back}
      </Link>
      <h1 className="text-white text-xl font-extrabold leading-tight">
        {L('Order details', 'ఆర్డర్ వివరాలు')}
      </h1>
      {order?.order_code && (
        <p className="text-green-300 text-sm mt-1 font-mono">{order.order_code}</p>
      )}
    </div>

    <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
      {loading ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center">
          <div className="w-9 h-9 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
        </div>
      ) : notFound || !order ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-3">
          <div className="text-4xl">🔍</div>
          <p className="font-semibold text-gray-600 text-sm">
            {L('Order not found', 'ఆర్డర్ కనబడలేదు')}
          </p>
          <Link href="/farmer/dashboard/orders" className="inline-block text-green-700 text-sm font-bold underline">
            {L('Back to orders', 'ఆర్డర్లకు తిరిగి వెళ్ళు')}
          </Link>
        </div>
      ) : (
        <>
          {/* Summary */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="text-base font-extrabold text-gray-900 leading-tight">
                  {order.produce_name || '—'}
                </p>
                <p className="text-xs text-gray-500 mt-0.5">
                  {order.quantity} {order.unit || 'kg'}
                  {order.total_price ? ` · ₹${order.total_price}` : ''}
                </p>
              </div>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusBadge(order.status)}`}>
                {statusText(order.status)}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 pt-3 border-t border-gray-100">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase">{L('Placed', 'పెట్టారు')}</p>
                <p className="text-xs font-semibold text-gray-700">{fmt(order.created_at)}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase">{L('Payment', 'చెల్లింపు')}</p>
                <p className="text-xs font-semibold text-gray-700">{paymentText(order)}</p>
                {(order.payment_method === 'upi' || order.payment_method === 'razorpay') && order.utr_number && (
                  <p className="text-[11px] text-gray-500 font-mono">UTR: {order.utr_number}</p>
                )}
              </div>
              {order.status !== 'declined' && order.status !== 'cancelled' && (
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">
                    {isDelivery ? tx.deliveryDateLabel : tx.pickupDateLabel}
                  </p>
                  <p className="text-xs font-semibold text-gray-700">
                    {order.fulfillment_date ? fmtDate(order.fulfillment_date) : L('Not set', 'సెట్ చేయలేదు')}
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Buyer */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-2">
            <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">{L('Buyer', 'కొనుగోలుదారు')}</p>
            <p className="text-base font-extrabold text-gray-900 leading-tight">{order.buyer_name || '—'}</p>
            {order.buyer_phone && (
              <a
                href={`tel:+91${order.buyer_phone}`}
                className="mt-1 w-full inline-flex items-center justify-center gap-2 bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700"
              >
                📞 {L('Call', 'కాల్')} · +91 {order.buyer_phone}
              </a>
            )}
            {order.delivery_alt_phone && (
              <p className="text-xs text-gray-500">{L('Alt phone', 'ప్రత్యామ్నాయ ఫోన్')}: +91 {order.delivery_alt_phone}</p>
            )}
          </div>

          {/* Fulfilment: pickup location or delivery address */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-2">
            <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
              {isDelivery ? L('Home delivery', 'ఇంటికి డెలివరీ') : isCourier ? L('Courier', 'కొరియర్') : L('Self pickup', 'స్వయంగా తీసుకోవడం')}
            </p>
            {(isDelivery || isCourier) && order.delivery_address ? (
              <>
                <p className="text-sm text-gray-800 leading-snug whitespace-pre-line">📦 {order.delivery_address}</p>
                {order.delivery_landmark && <p className="text-xs text-gray-600">📍 {order.delivery_landmark}</p>}
                {order.delivery_pincode && <p className="text-xs text-gray-600">PIN: {order.delivery_pincode}</p>}
              </>
            ) : order.pickup_location ? (
              <p className="text-sm text-gray-800">📍 {order.pickup_location}</p>
            ) : (
              <p className="text-xs text-gray-500">—</p>
